/**
 * Known crawlers, by category, for the robots.txt settings (ADR 0001). Two sources, both
 * bundled and reviewed with each release (the site never fetches lists at runtime):
 * - AI crawlers from ai.robots.txt (MIT; data/ai-bots.ts, generated by scripts/update-bots.mjs),
 * - everything else from our own short list (data/curated-bots.ts).
 * Pure.
 */
import { AI_BOTS } from './data/ai-bots.js';
import { CURATED_BOTS } from './data/curated-bots.js';

export const CATEGORIES = [
	{
		id: 'search',
		label: 'Search engines',
		description: 'Index the site for search results. Blocking them removes the site from those search engines.',
	},
	{
		id: 'ai-training',
		label: 'AI training',
		description: 'Collect content to train AI models or to sell as AI training data.',
	},
	{
		id: 'ai-search',
		label: 'AI search',
		description: 'Fetch pages for AI-powered search engines and answers, often with a link back.',
	},
	{
		id: 'ai-assistants',
		label: 'AI assistants and agents',
		description: 'Fetch pages when a person asks an AI assistant or agent to (chat, browsing, coding tools).',
	},
	{
		id: 'ai-other',
		label: 'Other AI crawlers',
		description: 'AI-related crawlers whose purpose is undocumented or unclear.',
	},
	{
		id: 'seo',
		label: 'SEO and marketing tools',
		description: 'Crawl for backlink, ranking and site-audit tools. Often heavy, rarely useful to the site itself.',
	},
	{
		id: 'social',
		label: 'Social link previews',
		description: 'Fetch a page to show its preview when a link is shared. Blocking them breaks link previews.',
	},
	{
		id: 'archive',
		label: 'Web archives',
		description: 'Save copies of pages for public web archives such as the Wayback Machine.',
	},
] as const;

export type CategoryId = (typeof CATEGORIES)[number]['id'];
export const CATEGORY_IDS: readonly CategoryId[] = CATEGORIES.map((c) => c.id);

export const isCategory = (value: unknown): value is CategoryId =>
	typeof value === 'string' && (CATEGORY_IDS as readonly string[]).includes(value);

/** Whether a crawler is known to obey robots.txt. */
export type Respects = 'yes' | 'no' | 'unknown';

export interface Bot {
	/** The user-agent token robots.txt uses, e.g. `GPTBot`. */
	name: string;
	category: CategoryId;
	operator: string;
	respects: Respects;
	description: string;
	/** Where the entry comes from. */
	source: 'ai.robots.txt' | 'curated';
}

/**
 * A robots.txt user-agent token: letters, digits, spaces and `._-/` (no line breaks or `:`, so
 * a token can never inject a directive). Checked for every bundled entry by the tests.
 */
export const BOT_NAME = /^[A-Za-z0-9][A-Za-z0-9 ._\-/]{0,79}$/;

/** Every known crawler, curated entries first within each category, then by name. */
export const BOTS: readonly Bot[] = [...CURATED_BOTS, ...AI_BOTS].sort(
	(a, b) =>
		CATEGORY_IDS.indexOf(a.category) - CATEGORY_IDS.indexOf(b.category) ||
		a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }),
);

export const botsIn = (category: CategoryId, bots: readonly Bot[] = BOTS) =>
	bots.filter((b) => b.category === category);
